import { esc } from '../ui.js';
export default function importPage({state,ui}) {
 if(state.imported) return `<section class="empty"><h2>הקליטה המקומית הסתיימה</h2><p>שתי רשומות פיקטיביות נוספו לרשימה. איפוס ההדגמה מאפשר להתחיל מחדש.</p><a class="outline" href="#records">פתיחת הרשומות</a></section>`;
 return `<section class="card"><h2>בדיקת נתונים לפני קליטה</h2><p>התנסו בבדיקת קובץ לדוגמה: שלוש שורות פיקטיביות, שתיים תקינות ואחת דורשת תיקון.</p><div class="notice">בהדגמה זו משתמשים בנתונים המצורפים בלבד.</div><button data-action="validate-import">בדיקת קובץ הדוגמה</button></section>${ui.importValidated?`<section class="card"><h2>תוצאות הבדיקה</h2><div class="table-wrap"><table><thead><tr><th>שורה</th><th>שם</th><th>אימייל</th><th>תוצאה</th></tr></thead><tbody><tr><td>1</td><td>ארגון מיובא 01</td><td>import1@example.com</td><td><span class="tag success">תקין</span></td></tr><tr><td>2</td><td>ארגון מיובא 02</td><td>import2@example.com</td><td><span class="tag success">תקין</span></td></tr><tr><td>3</td><td>ארגון מיובא 03</td><td>—</td><td>חסר אימייל · השורה לא תיקלט</td></tr></tbody></table></div><div class="form-actions"><button class="outline" data-action="cancel-import">ביטול</button><button data-action="commit-import">קליטת 2 רשומות תקינות</button></div></section>`:''}`;
}
